            ["memoryview.obj"] = "The underlying object of the memoryview.",
            ["memoryview.readonly"] = "A bool indicating whether the memory is read only.",
            ["memoryview.release"] = "release($self, /)\n--\n\nRelease the underlying buffer exposed by the memoryview object.",
