            ["property.__set__"] = "__set__($self, instance, value, /)\n--\n\nSet an attribute of instance to value.",
            ["property.__set_name__"] = "Method to set name of a property.",
            ["property.deleter"] = "Descriptor to obtain a copy of the property with a different deleter.",
