            ["slice.__reduce__"] = "Return state information for pickling.",
            ["slice.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["slice.indices"] = "S.indices(len) -> (start, stop, stride)\n\nAssuming a sequence of length len, calculate the start and stop\nindices, and the stride length of the extended slice described by\nS. Out of bounds indices are clipped in a manner consistent with the\nhandling of normal slices.",
            ["staticmethod"] = "staticmethod(function) -> method\n\nConvert a function to be a static method.\n\nA static method does not receive an implicit first argument.\nTo declare a static method, use this idiom:\n\n     class C:\n         @staticmethod\n         def f(arg1, arg2, argN):\n             ...\n\nIt can be called either on the class (e.g. C.f()) or on an instance\n(e.g. C().f()). Both the class and the instance are ignored, and\nneither is passed implicitly as the first argument to the method.\n\nStatic methods in Python are similar to those found in Java or C++.\nFor a more advanced concept, see the classmethod builtin.",
            ["staticmethod.__call__"] = "__call__($self, /, *args, **kwargs)\n--\n\nCall self as a function.",
            ["staticmethod.__get__"] = "__get__($self, instance, owner=None, /)\n--\n\nReturn an attribute of instance, which is of type owner.",
            ["staticmethod.__init__"] = "__init__($self, /, *args, **kwargs)\n--\n\nInitialize self.  See help(type(self)) for accurate signature.",
            ["staticmethod.__new__"] = "__new__($type, *args, **kwargs)\n--\n\nCreate and return a new object.  See help(type) for accurate signature.",
            ["staticmethod.__repr__"] = "__repr__($self, /)\n--\n\nReturn repr(self).",
            ["str"] = "str(object='') -> str\nstr(bytes_or_buffer[, encoding[, errors]]) -> str\n\nCreate a new string object from the given object. If encoding or\nerrors is specified, then the object must expose a data buffer\nthat will be decoded using the given encoding and error handler.\nOtherwise, returns the result of object.__str__() (if defined)\nor repr(object).\nencoding defaults to sys.getdefaultencoding().\nerrors defaults to 'strict'.",
            ["str.__add__"] = "__add__($self, value, /)\n--\n\nReturn self+value.",
            ["str.__contains__"] = "__contains__($self, key, /)\n--\n\nReturn bool(key in self).",
            ["str.__eq__"] = "__eq__($self, value, /)\n--\n\nReturn self==value.",
            ["str.__format__"] = "__format__($self, format_spec, /)\n--\n\nReturn a formatted version of the string as described by format_spec.",
